import re

import pytest


def title_of(html: str) -> str:
    """Return the text between the first `<title>` and the following `</title>`.

    Tag names are matched case-insensitively. The text between the tags is
    returned exactly as written (no stripping), and may span multiple lines.
    Returns "" if there is no `<title>`, or no `</title>` after it.
    Does not access the network.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_basic_title() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>No title here</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive_tags() -> None:
    assert title_of("<HTML><HEAD><TITLE>Upper</TITLE></HEAD></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  padded  </title>") == "  padded  "


def test_multiline_title() -> None:
    assert title_of("<title>line one\nline two</title>") == "line one\nline two"


def test_first_title_wins() -> None:
    assert title_of("<title>first</title><title>second</title>") == "first"


def test_unclosed_title() -> None:
    assert title_of("<html><title>never closed<body></body>") == ""


def test_closing_tag_without_opening() -> None:
    assert title_of("<html>oops</title></html>") == ""


def test_special_characters_untouched() -> None:
    assert title_of("<title>Tom &amp; Jerry © 2024</title>") == "Tom &amp; Jerry © 2024"


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title>a</title>", "a"),
        ("before<title>b</title>after", "b"),
        ("<p>x</p>", ""),
    ],
)
def test_parametrized(html: str, expected: str) -> None:
    assert title_of(html) == expected
